import { definePmNodeConverter } from './../pm-converters/types.js';
import type { AppEmbedData } from './../ricos-schema/next-schema/index.js';
import { Node_Type } from './../ricos-schema/next-schema/index.js';

import { hasOnlyDefaults } from './utils.js';

const DEFAULT_FALSE_PROPERTIES = [
  'hideImage',
  'hidePrice',
  'hideButton',
  'hideDescription',
  'hideDateTime',
  'hideLocation',
  'hideDuration',
] as const;

const DEFAULT_TRUE_PROPERTIES = ['hideRibbon'] as const;

const STYLE_DEFAULTS = {
  imageStyles: { imagePosition: 'START', aspectRatio: 'SQUARE', resizing: 'FILL' },
  ribbonStyles: { ribbonPlacement: 'PRODUCT_INFO' },
  cardStyles: { type: 'CONTAINED', alignment: 'START', titlePriceLayout: 'STACKED' },
  buttonStyles: { buttonSize: 'MEDIUM' },
} as const;

// TODO: Refactor when normalizeRichContent is removed and we can get rid of enum defaults
const filterDefaultData = (data: Record<string, any>): Record<string, any> => {
  const filteredData = Object.fromEntries(
    Object.entries(data).filter(
      ([key, value]) =>
        (!DEFAULT_FALSE_PROPERTIES.includes(key as (typeof DEFAULT_FALSE_PROPERTIES)[number]) ||
          value === true) &&
        (!DEFAULT_TRUE_PROPERTIES.includes(key as (typeof DEFAULT_TRUE_PROPERTIES)[number]) ||
          value === false)
    )
  );

  Object.entries(STYLE_DEFAULTS).forEach(([styleKey, defaults]) => {
    if (filteredData[styleKey] && hasOnlyDefaults(filteredData[styleKey], defaults)) {
      filteredData[styleKey] = undefined;
    }
  });

  return filteredData;
};

export const appEmbedConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.APP_EMBED],
    convert: node => {
      const { containerData, ...appEmbedData } = node.appEmbedData as any;
      return {
        type: Node_Type.APP_EMBED,
        attrs: {
          ...appEmbedData,
          containerData,
          id: node.id,
        },
      };
    },
  },
  fromPm: {
    types: [Node_Type.APP_EMBED],
    convert: node => {
      const { id, containerData, animation, ...data } = node.attrs || {};

      const finalData = filterDefaultData(data);

      return {
        type: Node_Type.APP_EMBED,
        id,
        nodes: [],
        appEmbedData: {
          ...(finalData as AppEmbedData),
          containerData,
          ...(animation ? { animation } : {}),
        } as any,
      };
    },
  },
});
