import { Box, Button, Loader, Search, SectionHelper, SidePanel } from '@wix/design-system';
import type { FC } from 'react';
import React, { useContext, useEffect, useState } from 'react';

import {
  EditorContext,
  ModalServiceContext,
  PluginsEventsContext,
  RicosContext,
} from './../../ricos-context/index.js';
import type { AppEmbedData } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import { debounce } from './../../_shared/debounce.js';
import { unreachable } from './../../_shared/uncreachable.js';
import { MEDIA_POPOVERS_BUTTONS_NAMES_BI, uuid } from './../../wix-rich-content-common/index.js';
import {
  getLowerCaseAppEmbedType,
  isTypeAppEmbed,
  toAppEmbedData,
} from './../utils.js';
import {
  FooterActions,
  Panel,
  PanelHeader,
  usePanelContainerElement,
} from './../../ui-components/index.js';

import type { ContentType } from '../constants.js';
import { contentTypeMap } from '../constants.js';
import {
  INSERT_VERTICAL_EMBED_CANCEL_BUTTON,
  INSERT_VERTICAL_EMBED_FOOTER_ACTIONS,
  INSERT_VERTICAL_EMBED_ITEMS_LIST,
  INSERT_VERTICAL_EMBED_MODAL,
  INSERT_VERTICAL_EMBED_SEARCH_INPUT,
} from '../data-hooks.js';
import { useVerticalEmbedRequestService } from '../services/fetch-vertical-embed-data.js';
import { ItemsList } from '../toolbar/items-list.js';
import type { EmbeddableItem } from '../types.js';
import { VERTICAL_EMBED_TYPE } from '../types.js';

type InsertModalProps = {
  nodeId?: string;
  componentData: AppEmbedData;
  modalId: string;
};

const visuallyHiddenStyle: React.CSSProperties = {
  position: 'absolute',
  width: 1,
  height: 1,
  overflow: 'hidden',
  clipPath: 'inset(50%)',
  whiteSpace: 'nowrap',
};

type InsertModalPropsState =
  | { status: 'LOADING'; requestId: string; searchText: string }
  | {
      status: 'READY';
      items: EmbeddableItem[];
      selectedItem: EmbeddableItem | undefined;
      searchText: string;
      showSelectionError: boolean;
    };

export const InsertModal: FC<InsertModalProps> = ({ componentData, nodeId, modalId }) => {
  const { t, isMobile } = useContext(RicosContext);
  const { getPublicCommands } = useContext(EditorContext);
  const modalService = useContext(ModalServiceContext) || {};
  const pluginsEvents = useContext(PluginsEventsContext);
  const { fetchVerticalEmbedItems } = useVerticalEmbedRequestService();
  const logBi = useBiNext({ modalId, pluginId: 'verticalEmbed', nodeId });
  const contentType: ContentType = contentTypeMap[componentData.type];
  const containerEl = usePanelContainerElement();
  const listboxId = `vertical-embed-items-list-${modalId}`;

  const [state, setState] = useState<InsertModalPropsState>({
    status: 'LOADING',
    searchText: '',
    requestId: uuid(),
  });

  useEffect(() => {
    fetchEmbedItems('');
  }, []);

  const fetchEmbedItems = debounce((inputString: string = '') => {
    const requestId = uuid();
    setState(() => ({
      status: 'LOADING',
      searchText: inputString,
      requestId,
    }));

    (async () => {
      try {
        const verticalApiType = getLowerCaseAppEmbedType(componentData.type);

        const items = isTypeAppEmbed(componentData.type)
          ? await fetchVerticalEmbedItems(verticalApiType, inputString)
          : [];

        setState(prev => {
          if (prev.status === 'LOADING' && prev.requestId !== requestId) {
            return prev;
          }

          return {
            status: 'READY',
            items: items ?? [],
            selectedItem: undefined,
            searchText: inputString,
            showSelectionError: false,
          };
        });
      } catch (e) {
        console.error('Failed to load products', e);

        // we don't have error state in the design, so we just show an empty state for now
        setState(prev => {
          if (prev.status === 'LOADING' && prev.requestId !== requestId) {
            return prev;
          }

          return {
            status: 'READY',
            items: [],
            selectedItem: undefined,
            searchText: inputString,
            showSelectionError: false,
          };
        });
      }
    })();
  }, 300);

  const closeModal = () => modalService.closeModal(modalId);

  const onSave = () => {
    pluginsEvents.publishPluginPopoverClick?.({
      pluginId: VERTICAL_EMBED_TYPE,
      buttonName: MEDIA_POPOVERS_BUTTONS_NAMES_BI.embed,
    });

    if (state.status !== 'READY' || !state.selectedItem) {
      setState(prev => ({ ...prev, showSelectionError: true }));
      return;
    }

    const embedData = toAppEmbedData(state.selectedItem, componentData, t);

    insertEmbedNode(embedData);

    closeModal();
  };

  const insertEmbedNode = (verticalEmbed: AppEmbedData) => {
    const publicCommands = getPublicCommands();
    setTimeout(
      () =>
        nodeId
          ? publicCommands?.setBlock(nodeId, VERTICAL_EMBED_TYPE, {
              ...verticalEmbed,
              error: false,
              loading: false,
            })
          : publicCommands?.insertBlockWithBlankLines(VERTICAL_EMBED_TYPE, verticalEmbed),
      50
    );
    closeModal();
  };

  if (!componentData) {
    return null;
  }

  return (
    <Panel
      height={isMobile ? '100%' : '540px'}
      closeButtonProps={{ onClick: closeModal }}
      dataHook={INSERT_VERTICAL_EMBED_MODAL}
    >
      <PanelHeader title={t(`Embed_Vertical_${contentType}_Title`)} />

      {/* oxlint-disable-next-line jsx-a11y/no-static-element-interactions */}
      <div
        // capture phase: WDS Search (InputWithOptions) swallows ArrowDown before it bubbles
        onKeyDownCapture={(e: React.KeyboardEvent<HTMLDivElement>) => {
          // ArrowDown moves from the search input into the items list
          if (e.key !== 'ArrowDown') {
            return;
          }

          const option = document
            .getElementById(listboxId)
            ?.querySelector<HTMLElement>('[role="option"][tabindex="0"]');

          if (option) {
            e.preventDefault();
            e.stopPropagation();
            option.focus();
          }
        }}
      >
        <Box padding="SP3">
          <Search
            size="small"
            value={state.searchText}
            onChange={e => {
              fetchEmbedItems(e.target.value);

              logBi({
                dataHook: INSERT_VERTICAL_EMBED_SEARCH_INPUT,
                value: e.target.value,
              });
            }}
            onClear={() => fetchEmbedItems('')}
            placeholder={t(`Embed_Vertical_${contentType}_Search_Placeholder`)}
            ariaLabel={t(`Embed_Vertical_${contentType}_Search_Placeholder`)}
            ariaControls={listboxId}
            dataHook={INSERT_VERTICAL_EMBED_SEARCH_INPUT}
          />
        </Box>
      </div>
      <span style={visuallyHiddenStyle} aria-live="polite" role="status">
        {state.status === 'READY' &&
          (state.items.length === 0
            ? // reuse the visible empty-state title so the announcement is already translated
              t(
                `Embed_Vertical_${contentType}_EmptyState_${
                  state.searchText.length > 0 ? 'NoResults' : 'NoItems'
                }_Title`
              )
            : t('Embed_Vertical_SearchResults_AriaLive', { count: state.items.length }))}
      </span>
      {(() => {
        switch (state.status) {
          case 'LOADING':
            return (
              <Box align="center" verticalAlign="middle" height="252px">
                <Loader />
              </Box>
            );
          case 'READY':
            return (
              <>
                <Box direction="vertical" paddingBottom="SP3" overflow="auto">
                  <ItemsList
                    selectedItem={state.selectedItem}
                    items={state.items}
                    hasActiveSearch={state.searchText.length > 0}
                    onClick={item => {
                      logBi({
                        dataHook: INSERT_VERTICAL_EMBED_ITEMS_LIST,
                        value: contentType,
                      });

                      setState(prev => {
                        if (prev.status === 'READY') {
                          return {
                            ...prev,
                            showSelectionError: false,
                            selectedItem: item.id === prev.selectedItem?.id ? undefined : item,
                          };
                        }
                        return prev;
                      });
                    }}
                    contentType={contentType}
                    modalRef={containerEl}
                    listboxId={listboxId}
                  />
                </Box>
                {state.showSelectionError && (
                  <Box padding="SP3" position="absolute" bottom="40px" role="alert">
                    <SectionHelper
                      appearance="danger"
                      title={t('Embed_Vertical_Nothing_Selected_Error_Title')}
                      showCloseButton
                      onClose={() => setState(prev => ({ ...prev, showSelectionError: false }))}
                    >
                      {t('Embed_Vertical_Nothing_Selected_Error_Description')}
                    </SectionHelper>
                  </Box>
                )}
              </>
            );
          default:
            unreachable(state);
            return null;
        }
      })()}
      <SidePanel.Footer showDivider>
        {state.status === 'READY' && state.items.length === 0 && state.searchText.length === 0 ? (
          <Box align="right" gap="SP2">
            <Button
              onClick={() => {
                logBi({
                  dataHook: INSERT_VERTICAL_EMBED_CANCEL_BUTTON,
                });
                closeModal();
              }}
              priority="primary"
              dataHook={INSERT_VERTICAL_EMBED_CANCEL_BUTTON}
              size="small"
            >
              {t('Embed_Vertical_Close_Button')}
            </Button>
          </Box>
        ) : (
          <FooterActions
            dataHook={INSERT_VERTICAL_EMBED_FOOTER_ACTIONS}
            onCancel={closeModal}
            logBi={logBi}
            onSave={onSave}
            saveButtonLabel={t('Embed_Vertical_Add_Button')}
          />
        )}
      </SidePanel.Footer>
    </Panel>
  );
};
