import { Catalog } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useEffect, useState } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { useModalService } from './../../ricos-modals/modal-service-provider.js';
import type { IToolbarItem } from './../../ricos-types/index.js';
import { ToolbarButton } from './../../_shared/toolbar-button/toolbar-button.js';

type Props = {
  toolbarItem: IToolbarItem;
  dataHook?: string;
};

export const PresetsButton: FC<Props> = ({ toolbarItem, dataHook }) => {
  const { t, isMobile } = useContext(RicosContext) || {};
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);
  const [isActive, setIsActive] = useState(toolbarItem.attributes.active);
  const modalService = useModalService();

  useEffect(() => {
    modalService.onModalOpened(() => {
      setIsActive(Boolean(toolbarItem.attributes.active));
    });

    modalService.onModalClosed(() => {
      setIsActive(Boolean(toolbarItem.attributes.active));
    });
  }, [modalService]);

  return (
    <ToolbarButton
      prefix={Catalog}
      onClick={() => toolbarItem.commands?.click({ isMobile, referenceElement })}
      dataHook={dataHook}
      label={t('Embed_Vertical_Presets_Tooltip')}
      ref={setReferenceElement}
      active={isActive}
    />
  );
};
