import { Button, Loader, MediaOverlay, Text } from '@wix/design-system';
import { Link, StatusAlertFilled } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext } from 'react';

import { ModalServiceContext } from './../../ricos-context/modal-context.js';
import { RicosContext } from './../../ricos-context/ricos-context.js';
import type { AppEmbedData as AppEmbedDataLegacy } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { AppEmbedData, AppEmbedNode } from './../../ricos-schema/next-schema/index.js';
import type { PluginProps } from './../../ricos-types/index.js';
import type { Editor } from './../../tiptap/core/index.js';
import { appEmbedConverter } from './../app-embed-converter.js';

import { verticalEmbedModals } from '../constants.js';
import { InsertModal } from '../modals/insert-modal.js';
import type { VerticalEmbedErrorType, VerticalEmbedPluginViewerConfig } from '../types.js';
import { VerticalEmbedViewer } from '../viewer/vertical-embed-viewer.js';
import classes from './component-scss.js';

export const AppEmbed: React.FC<PluginProps> = ({ settings, node, editor }) => {
  const ricosNode = React.useMemo(
    () => appEmbedConverter.fromPm.convert(node.toJSON()) as AppEmbedNode,
    [node]
  );

  const { loading, error } = node.attrs;

  return (
    <>
      {loading && <VerticalEmbedLoading />}
      {error && (
        <VerticalEmbedError
          editor={editor}
          componentData={ricosNode.appEmbedData as AppEmbedData}
          settings={settings as VerticalEmbedPluginViewerConfig}
          nodeId={node.attrs.id}
          error={error as VerticalEmbedErrorType}
        />
      )}
      {!loading && !error && (
        <VerticalEmbedViewer
          nodeId={node.attrs.id}
          componentData={ricosNode.appEmbedData as AppEmbedData}
          settings={settings as VerticalEmbedPluginViewerConfig}
        />
      )}
    </>
  );
};

const VerticalEmbedLoading = () => {
  return (
    <div className={classes.card}>
      <div className={classes.container}>
        <div className={classes.content}>
          <Loader size="small" />
        </div>
      </div>
    </div>
  );
};

const VerticalEmbedError = ({
  editor,
  componentData,
  settings,
  nodeId,
  error = 'NOT_FOUND',
}: {
  editor?: Editor;
  componentData: AppEmbedData;
  settings: VerticalEmbedPluginViewerConfig;
  nodeId: string;
  error?: VerticalEmbedErrorType;
}) => {
  const { t } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext);

  const handleReplace = () => {
    if (!editor || !modalService) {
      return;
    }

    modalService.openModal({
      id: verticalEmbedModals.replace,
      Component: InsertModal,
      componentProps: {
        modalId: verticalEmbedModals.replace,
        componentData: componentData as unknown as AppEmbedDataLegacy,
        nodeId,
      },
      layout: 'floating',
      positioning: {
        referenceElement: editor.view.dom,
        placement: 'bottom-start',
      },
      withTransition: true,
      enableDrag: true,
      dragHandleSelector: '[data-drag-handler]',
      disableArrowNavigation: true,
      onClickOutside: {
        on: 'pointerup',
        handler: () => {},
      },
    });
  };

  const getErrorTranslations = () => {
    const isDeleted = error === 'NOT_FOUND';

    switch (componentData.type) {
      case 'PRODUCT':
        return {
          title: t(
            isDeleted
              ? 'VerticalEmbed_Product_Error_Title'
              : 'VerticalEmbed_Product_Fetch_Error_Title'
          ),
          subtitle: t(
            isDeleted
              ? 'VerticalEmbed_Product_Error_Subtitle'
              : 'VerticalEmbed_Product_Fetch_Error_Subtitle'
          ),
        };
      case 'EVENT':
        return {
          title: t(
            isDeleted ? 'VerticalEmbed_Event_Error_Title' : 'VerticalEmbed_Event_Fetch_Error_Title'
          ),
          subtitle: t(
            isDeleted
              ? 'VerticalEmbed_Event_Error_Subtitle'
              : 'VerticalEmbed_Event_Fetch_Error_Subtitle'
          ),
        };
      case 'BOOKING':
        return {
          title: t(
            isDeleted
              ? 'VerticalEmbed_Booking_Error_Title'
              : 'VerticalEmbed_Booking_Fetch_Error_Title'
          ),
          subtitle: t(
            isDeleted
              ? 'VerticalEmbed_Booking_Error_Subtitle'
              : 'VerticalEmbed_Booking_Fetch_Error_Subtitle'
          ),
        };
      default:
        return {
          title: t(isDeleted ? 'VerticalEmbed_Error_Title' : 'VerticalEmbed_Fetch_Error_Title'),
          subtitle: t(
            isDeleted ? 'VerticalEmbed_Error_Subtitle' : 'VerticalEmbed_Fetch_Error_Subtitle'
          ),
        };
    }
  };

  const errorTranslations = getErrorTranslations();

  return (
    <MediaOverlay
      skin="dark"
      media={
        <VerticalEmbedViewer
          nodeId={nodeId}
          componentData={componentData}
          settings={settings}
          helpers={{}}
        />
      }
    >
      <MediaOverlay.Content visible="always">
        <div className={classes.overlay}>
          <div className={classes.errorContainer}>
            <div className={classes.errorInfo}>
              <div className={classes.errorIcon}>
                <StatusAlertFilled color="white" />
              </div>
              <div>
                <Text light weight="bold">
                  {errorTranslations.title}
                </Text>
                <br />
                <Text light>{errorTranslations.subtitle}</Text>
              </div>
            </div>
            {editor && (
              <Button prefixIcon={<Link />} priority="secondary" onClick={handleReplace}>
                {t('VerticalEmbed_Error_Button')}
              </Button>
            )}
          </div>
        </div>
      </MediaOverlay.Content>
    </MediaOverlay>
  );
};
