import classNames from 'classnames';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/ricos-context.js';
import type { AppEmbedData } from './../../ricos-schema/next-schema/index.js';
import type {
  AppEmbedData_ImageStyles_Position,
  AppEmbedData_PricingData,
} from './../../ricos-schema/next-schema/generated/ricos_document.js';
import {
  VERTICAL_EMBED_BUTTON,
  VERTICAL_EMBED_TITLE,
} from './../data-hooks.js';

import { MAX_BUTTON_TEXT_LENGTH, MAX_RIBBON_TEXT_LENGTH, MAX_TITLE_LENGTH } from '../constants.js';
import styles from './card-content-scss.js';
import { Description } from './description.js';
import { Ribbon } from './ribbon.js';

type CardContentProps = {
  title: string;
  buttonText: string;
  componentData: AppEmbedData;
  imagePosition?: AppEmbedData_ImageStyles_Position;
  contentClasses?: string;
  ribbonText?: string;
  ribbonPlacement?: 'IMAGE' | 'PRODUCT_INFO';
};

export const CardContent: React.FC<CardContentProps> = props => {
  const { t } = useContext(RicosContext);

  const { title, buttonText, contentClasses, ribbonPlacement, componentData, ribbonText } = props;

  if (!componentData.cardStyles) {
    componentData.cardStyles = {};
  }

  if (!componentData.cardStyles.titlePriceLayout) {
    componentData.cardStyles.titlePriceLayout = 'STACKED';
  }

  const shouldShowButton = !componentData?.hideButton;
  const shouldShowRibbon =
    !(componentData?.hideRibbon ?? true) &&
    (!ribbonPlacement || ribbonPlacement === 'PRODUCT_INFO');

  return (
    <div className={classNames(styles.content, contentClasses)}>
      <div className={styles.contentText}>
        {shouldShowRibbon && <RibbonTag ribbonText={ribbonText} />}
        <TitleAndPrice title={title} componentData={componentData} t={t} />
        <Description componentData={componentData} />
      </div>
      {shouldShowButton && <ActionButton buttonText={buttonText} t={t} />}
    </div>
  );
};

const TitleAndPrice = ({
  title,
  componentData,
  t,
}: {
  title: string;
  componentData: AppEmbedData;
  t: (key: string) => string;
}) => {
  const shouldShowPricing =
    componentData.pricingData &&
    !componentData.hidePrice &&
    (componentData.pricingData.valueFrom ||
      componentData.pricingData.discountedValue ||
      componentData.pricingData.pricingPlanId);

  return (
    <div className={styles.titlePriceContainer}>
      <div className={styles.title} data-hook={VERTICAL_EMBED_TITLE}>
        {truncateTitle(title)}
      </div>
      {shouldShowPricing && <PricingInfo pricingData={componentData.pricingData} t={t} />}
    </div>
  );
};

const PricingInfo = ({
  pricingData,
  t,
}: {
  pricingData?: AppEmbedData_PricingData;
  t: (key: string) => string;
}) => {
  const { valueFrom, valueTo, discountedValue, currency, pricingPlanId } = pricingData || {};

  const formatPrice = (price: string): string => {
    const numericPrice = parseFloat(price);
    if (isNaN(numericPrice)) {
      return price;
    }

    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency,
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(numericPrice);
  };

  if (pricingPlanId) {
    return (
      <div className={classNames(styles.pricing, styles.priceOriginal)}>
        <span className={classNames(styles.price)}>{t('VerticalEmbed_Pricing_Plan')}</span>
      </div>
    );
  }

  return (
    <div className={classNames(styles.pricing, styles.priceOriginal)}>
      {valueTo !== valueFrom && (
        <span className={classNames(styles.price)}>{t('VerticalEmbed_From_Price')}</span>
      )}

      {valueFrom && (
        <span
          className={classNames(styles.price, styles.priceOriginal, {
            [styles.priceStrikethrough]: discountedValue && discountedValue !== valueFrom,
          })}
        >
          {formatPrice(valueFrom)}
        </span>
      )}

      {discountedValue && discountedValue !== valueFrom && (
        <span className={classNames(styles.price, styles.priceDiscounted)}>
          {formatPrice(discountedValue)}
        </span>
      )}
    </div>
  );
};

const RibbonTag = ({ ribbonText }: { ribbonText?: string }) => (
  <div className={styles.ribbon}>
    <Ribbon>{truncateRibbonText(ribbonText || '')}</Ribbon>
  </div>
);

const ActionButton = ({ buttonText }: { buttonText: string; t: (key: string) => string }) => (
  <div data-hook={VERTICAL_EMBED_BUTTON} className={styles.button}>
    <div className={styles.buttonText}>{truncateButtonText(buttonText)}</div>
  </div>
);

const truncateTitle = (title: string): string => {
  return title.length <= MAX_TITLE_LENGTH ? title : `${title.substring(0, MAX_TITLE_LENGTH)}...`;
};

const truncateButtonText = (text: string): string => {
  return text.length <= MAX_BUTTON_TEXT_LENGTH
    ? text
    : `${text.substring(0, MAX_BUTTON_TEXT_LENGTH)}...`;
};

const truncateRibbonText = (text: string): string => {
  return text.length <= MAX_RIBBON_TEXT_LENGTH
    ? text
    : `${text.substring(0, MAX_RIBBON_TEXT_LENGTH)}...`;
};
