import { SidePanel, Tabs, TextButton } from '@wix/design-system';
import { Design, Revert } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { ModalServiceContext, RicosContext } from './../../ricos-context/index.js';
import { logInvariant } from './../../_shared/log-invariant.js';
import { PmNodeType } from './../../_shared/pm-node-types.js';
import { useNodeAttrs } from './../../_shared/use-node-attrs.js';
import {
  SETTINGS_VERTICAL_EMBED_MODAL,
  SETTINGS_VERTICAL_EMBED_TABS,
} from './../data-hooks.js';
import { FLOATING_PLUGIN_TOOLBAR } from './../../toolbars-v3/index.js';
import {
  Panel,
  PanelHeader,
  useClickOutside,
  usePanelContainerElement,
} from './../../ui-components/index.js';

import { verticalEmbedModals } from '../constants.js';
import { DesignTab } from './design-tab.js';
import { LayoutTab } from './layout-tab.js';
import { Presets } from './presets.js';
import classes from './settings-modal-scss.js';
import { SettingsTab } from './settings-tab.js';

type SettingsModalProps = {
  nodeId: string;
  activeTab: 'settings' | 'design';
  config: $TSFixMe;
  referenceElement: HTMLElement | undefined;
  initialViewMode: 'presets' | 'custom';
  modalId: string;
};

export const SettingsModal: FC<SettingsModalProps> = ({
  nodeId,
  activeTab,
  config,
  referenceElement,
  initialViewMode,
  modalId,
}) => {
  const modalService = useContext(ModalServiceContext) || {};
  const containerEl = usePanelContainerElement();
  const { t, isMobile } = useContext(RicosContext);
  const [activeId, setActiveId] = useState<'settings' | 'layout' | 'design'>(activeTab);
  const { pmNodeAttrs, patchPmNodeAttrs } = useNodeAttrs(nodeId, PmNodeType.APP_EMBED);
  const isColorPickerModalOpen = () => modalService.isModalOpen(verticalEmbedModals.colorPicker);
  const [viewMode] = useState<'presets' | 'custom'>(initialViewMode);

  const closeModal = () => modalService.closeModal(modalId);

  const resetLayoutToDefaults = () => {
    if (!patchPmNodeAttrs) {
      return;
    }

    patchPmNodeAttrs({
      imageStyles: null,
      cardStyles: null,
      ribbonStyles: null,
    });
  };

  const resetDesignToDefaults = () => {
    if (!patchPmNodeAttrs) {
      return;
    }

    patchPmNodeAttrs({
      cardStyles: null,
      imageStyles: null,
      buttonStyles: null,
      ribbonStyles: null,
    });
  };

  const resetSettingsToDefaults = () => {
    if (!patchPmNodeAttrs) {
      return;
    }

    const baseSettings: Record<string, any> = {
      hideImage: undefined,
      hideButton: undefined,
      hideRibbon: undefined,
      buttonStyles: {
        ...pmNodeAttrs.buttonStyles,
        buttonText: undefined,
      },
      ...(pmNodeAttrs.ribbonStyles && {
        ribbonStyles: {
          ...pmNodeAttrs.ribbonStyles,
          ribbonText: undefined,
        },
      }),
    };

    const embedType = pmNodeAttrs.type as string;
    if (embedType === 'PRODUCT') {
      patchPmNodeAttrs({
        ...baseSettings,
        hidePrice: undefined,
      });
    } else if (embedType === 'EVENT') {
      patchPmNodeAttrs({
        ...baseSettings,
        hidePrice: undefined,
        hideDateTime: undefined,
        hideLocation: undefined,
      });
    } else if (embedType === 'BOOKING') {
      patchPmNodeAttrs({
        ...baseSettings,
        hidePrice: undefined,
        hideDuration: undefined,
        hideLocation: undefined,
      });
    } else {
      patchPmNodeAttrs(baseSettings);
    }
  };

  useClickOutside({
    containerRef: { current: containerEl },
    onClickOutside: (e: MouseEvent | TouchEvent) => {
      const target = e.target as HTMLElement | null;

      if (referenceElement?.contains(target as Node)) {
        return;
      }

      closeModal();
    },
    disable: isColorPickerModalOpen(),
  });

  if (!pmNodeAttrs) {
    logInvariant(new Error('App embed settings: node attrs not found'));
    return null;
  }

  return (
    <div className={classes.modal}>
      <Panel
        onCloseButtonClick={() => modalService.closeModal(modalId)}
        dataHook={SETTINGS_VERTICAL_EMBED_MODAL}
        maxHeight={isMobile ? undefined : 590}
      >
        <PanelHeader title={t('Embed_Vertical_Settings_Modal_Header')} />

        {viewMode === 'presets' && <Presets patchPmNodeAttrs={patchPmNodeAttrs} nodeId={nodeId} />}

        {viewMode === 'custom' && (
          <>
            <Tabs
              dataHook={SETTINGS_VERTICAL_EMBED_TABS}
              size="small"
              alignment="center"
              type="uniformFull"
              minWidth={0}
              activeId={activeId}
              onClick={value => setActiveId(value.id as 'settings' | 'layout' | 'design')}
              items={[
                { id: 'settings', title: t('Embed_Vertical_Settings_Modal_Settings_Tab') },
                { id: 'layout', title: t('Embed_Vertical_Settings_Modal_Layout_Tab') },
                { id: 'design', title: t('Embed_Vertical_Settings_Modal_Design_Tab') },
              ]}
            />
            {activeId === 'settings' && (
              <SettingsTab pmNodeAttrs={pmNodeAttrs} patchPmNodeAttrs={patchPmNodeAttrs} />
            )}
            {activeId === 'layout' && (
              <LayoutTab
                nodeId={nodeId}
                modalId={verticalEmbedModals.settings}
                pmNodeAttrs={pmNodeAttrs}
                patchPmNodeAttrs={patchPmNodeAttrs}
              />
            )}
            {activeId === 'design' && (
              <DesignTab
                nodeId={nodeId}
                config={config}
                modalId={verticalEmbedModals.settings}
                pmNodeAttrs={pmNodeAttrs}
                patchPmNodeAttrs={patchPmNodeAttrs}
              />
            )}
          </>
        )}

        <SidePanel.Footer>
          <div className={classes.centeredFooter}>
            {viewMode === 'presets' && (
              <TextButton
                prefixIcon={<Design />}
                size="small"
                onClick={() => {
                  modalService.closeModal(modalId);
                  modalService.openModal({
                    id: verticalEmbedModals.settings,
                    Component: SettingsModal,
                    withTransition: true,
                    enableDrag: !isMobile,
                    dragHandleSelector: '[data-drag-handler]',
                    layout: isMobile ? 'fullscreen' : 'floating',
                    componentProps: {
                      referenceElement,
                      nodeId,
                      initialViewMode: 'custom',
                      activeTab: 'settings',
                      config,
                      modalId: verticalEmbedModals.settings,
                    },
                    positioning: {
                      referenceElement:
                        referenceElement?.closest(`[data-hook~=${FLOATING_PLUGIN_TOOLBAR}]`) ??
                        referenceElement ??
                        undefined,
                      placement: 'right-start',
                    },
                    focusReturnElement: referenceElement ?? undefined,
                    disableArrowNavigation: true,
                    onClickOutside: {
                      on: 'pointerup',
                      handler: () => {},
                    },
                  });
                }}
              >
                {t('Embed_Vertical_Settings_Modal_Customize_Button')}
              </TextButton>
            )}

            {viewMode === 'custom' && activeId === 'settings' && (
              <TextButton prefixIcon={<Revert />} size="small" onClick={resetSettingsToDefaults}>
                {t('Embed_Vertical_Settings_Modal_Reset_Settings_Button')}
              </TextButton>
            )}

            {viewMode === 'custom' && activeId === 'layout' && (
              <TextButton prefixIcon={<Revert />} size="small" onClick={resetLayoutToDefaults}>
                {t('Embed_Vertical_Settings_Modal_Reset_Layout_Button')}
              </TextButton>
            )}

            {viewMode === 'custom' && activeId === 'design' && (
              <TextButton prefixIcon={<Revert />} size="small" onClick={resetDesignToDefaults}>
                {t('Embed_Vertical_Settings_Modal_Reset_Design_Button')}
              </TextButton>
            )}
          </div>
        </SidePanel.Footer>
      </Panel>
    </div>
  );
};
