import {
  DateChecked,
  DateCheckedSmall,
  Order,
  OrderSmall,
  WixBooking,
  WixBookingSmall,
} from '@wix/wix-ui-icons-common/lazy';

import type { ModalService } from './../ricos-modals/modal-service.js';
import { AppEmbedData_AppType } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { EditorPluginCreator, QuickAction } from './../ricos-types/index.js';
import {
  Node_Type,
  RicosPluginToolbarNames,
  quickActionsModalSections,
} from './../ricos-types/index.js';
import { posToDOMRect } from './../tiptap/index.js';
import type { Editor } from './../tiptap/core/index.js';

import { appEmbedConverter } from './app-embed-converter.js';
import { verticalEmbedModals, verticalEmbedProviders } from './constants.js';
import { DEFAULTS } from './defaults.js';
import { getAddButtons } from './get-add-buttons.js';
import { getToolbarButtons } from './get-toolbar-buttons.js';
import { InsertModal } from './modals/insert-modal.js';
import { tiptapExtensions } from './tiptap/tiptap.js';
import type { VerticalEmbedPluginEditorConfig } from './types.js';
import { VERTICAL_EMBED_TYPE } from './types.js';

export const pluginVerticalEmbed: EditorPluginCreator<VerticalEmbedPluginEditorConfig> = config => {
  const pluginConfig = {
    type: 'verticalEmbed' as const,
    ...DEFAULTS.config,
    ...config,
  };
  return {
    config: pluginConfig,
    type: VERTICAL_EMBED_TYPE,
    tiptapExtensions,
    pmMarkConverters: [],
    pmNodeConverters: [appEmbedConverter],
    toolbar: {
      names: [RicosPluginToolbarNames.APP_EMBED],
      getButtons: (config, services) => getToolbarButtons(config, services),
    },
    getAddButtons: (config, services) => getAddButtons(config, services),
    getQuickActions: ({ config, pluginServices }) => {
      const {
        exposeEmbedButtons = [
          verticalEmbedProviders.product,
          verticalEmbedProviders.booking,
          verticalEmbedProviders.event,
        ],
      } = config || {};
      const isMobile = pluginServices?.context.isMobile;

      const toggleInsertModal = ({
        id,
        type,
        modalService,
        editor,
      }: {
        id: string;
        type: AppEmbedData_AppType;
        modalService: ModalService;
        editor: Editor;
      }) =>
        modalService?.togglePluginPanel({
          id,
          Component: InsertModal,
          componentProps: {
            componentData: { type },
            modalId: id,
          },
          positioning: {
            referenceElement: {
              getBoundingClientRect: () =>
                posToDOMRect(
                  editor.view,
                  editor.view.state.selection.from,
                  editor.view.state.selection.to
                ),
            },
            placement: 'bottom-start',
          },
          isMobile,
        });

      const actions: QuickAction[] = [];

      if (exposeEmbedButtons.includes(verticalEmbedProviders.product)) {
        actions.push({
          id: `${Node_Type.APP_EMBED}.product`,
          title: 'QuickActionsPlugin_ActionTitle_Product',
          icon: isMobile ? Order : OrderSmall,
          section: quickActionsModalSections.EmbedWix,
          tags: [
            'item',
            'merchandise',
            'product card',
            'shop item',
            'e-commerce',
            'online store',
            'store item',
          ],
          command: ({ modalService, editor }) => {
            toggleInsertModal({
              id: verticalEmbedModals.insertProduct,
              type: AppEmbedData_AppType.PRODUCT,
              modalService,
              editor,
            });
          },
        });
      }

      if (exposeEmbedButtons.includes(verticalEmbedProviders.event)) {
        actions.push({
          id: `${Node_Type.APP_EMBED}.event`,
          title: 'QuickActionsPlugin_ActionTitle_Event',
          icon: isMobile ? DateChecked : DateCheckedSmall,
          section: quickActionsModalSections.EmbedWix,
          tags: ['calendar', 'meeting', 'appointment', 'schedule', 'date', 'time'],
          command: ({ modalService, editor }) => {
            toggleInsertModal({
              id: verticalEmbedModals.insertEvent,
              type: AppEmbedData_AppType.EVENT,
              modalService,
              editor,
            });
          },
        });
      }

      if (exposeEmbedButtons.includes(verticalEmbedProviders.booking)) {
        actions.push({
          id: `${Node_Type.APP_EMBED}.service`,
          title: 'QuickActionsPlugin_ActionTitle_Service',
          icon: isMobile ? WixBooking : WixBookingSmall,
          section: quickActionsModalSections.EmbedWix,
          tags: ['reservation', 'appointment', 'schedule', 'time', 'calendar', 'ticket', 'booking'],
          command: ({ modalService, editor }) => {
            toggleInsertModal({
              id: verticalEmbedModals.insertBooking,
              type: AppEmbedData_AppType.BOOKING,
              modalService,
              editor,
            });
          },
        });
      }

      return actions;
    },
  };
};
