import {
  Accordion,
  Box,
  Dropdown,
  FormField,
  Text,
  Thumbnail,
  Tooltip,
  accordionItemBuilder,
} from '@wix/design-system';
import {
  AlignCenterVerticallySmall,
  AlignLeftSmall,
  AlignRightSmall,
  BadgeSmall,
  HorizontalRatioSmall,
  ImageSmall,
  LayoutSplitSmall,
  LayoutTwoColumnsSplitSmall,
  ObjectPositionLeftSmall,
  ObjectPositionRightSmall,
  ObjectPositionTopSmall,
  SquareRatioSmall,
} from '@wix/wix-ui-icons-common/lazy';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/ricos-context.js';
import {
  AppEmbedData_CardStyles_Alignment,
  AppEmbedData_ImageStyles_AspectRatio,
  AppEmbedData_ImageStyles_Position,
  AppEmbedData_ImageStyles_Resizing,
  AppEmbedData_RibbonStyles_Placement,
} from './../../ricos-schema/next-schema/generated/ricos_document.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import type { PmAppEmbedNode } from './../../_shared/pm-node-types.js';
import { unreachable } from './../../_shared/uncreachable.js';
import { usePanelContainerElement } from './../../ui-components/index.js';

import { TITLE_PRICE_LAYOUT } from '../viewer/vertical-embed-styles.js';

type Props = {
  nodeId: string;
  modalId: string;
  pmNodeAttrs: PmAppEmbedNode['attrs'];
  patchPmNodeAttrs: (data: Partial<PmAppEmbedNode['attrs']>) => void;
};

export const LayoutTab: React.FC<Props> = ({ nodeId, modalId, pmNodeAttrs, patchPmNodeAttrs }) => {
  const { t, languageDir } = useContext(RicosContext);
  const isRTL = languageDir === 'rtl';
  const containerEl = usePanelContainerElement();

  const logBi = useBiNext({ modalId, pluginId: 'verticalEmbed', nodeId });

  const position =
    pmNodeAttrs?.imageStyles?.imagePosition || AppEmbedData_ImageStyles_Position.START;
  const ratio =
    pmNodeAttrs?.imageStyles?.aspectRatio || AppEmbedData_ImageStyles_AspectRatio.SQUARE;
  const resizing = pmNodeAttrs?.imageStyles?.resizing || AppEmbedData_ImageStyles_Resizing.FILL;
  const alignment = pmNodeAttrs?.cardStyles?.alignment || AppEmbedData_CardStyles_Alignment.START;
  const titlePriceLayout = pmNodeAttrs?.cardStyles?.titlePriceLayout || TITLE_PRICE_LAYOUT.STACKED;
  const ribbonPlacement =
    pmNodeAttrs?.ribbonStyles?.ribbonPlacement || AppEmbedData_RibbonStyles_Placement.PRODUCT_INFO;

  type StyleUpdateKey =
    | 'position'
    | 'ratio'
    | 'resizing'
    | 'alignment'
    | 'titlePriceLayout'
    | 'ribbonPlacement';

  const updateStyles = (updates: Partial<Record<StyleUpdateKey, string>>) => {
    const imageUpdates: Record<string, string> = {};
    const cardUpdates: Record<string, string> = {};
    const ribbonUpdates: Record<string, string> = {};

    Object.entries(updates).forEach(([key, value]) => {
      const styleKey = key as StyleUpdateKey;
      switch (styleKey) {
        case 'position':
          imageUpdates.imagePosition = value.toUpperCase();
          break;
        case 'ratio':
          imageUpdates.aspectRatio = value.toUpperCase();
          break;
        case 'resizing':
          imageUpdates.resizing = value.toUpperCase();
          break;
        case 'alignment':
          cardUpdates.alignment = value.toUpperCase();
          break;
        case 'titlePriceLayout':
          cardUpdates.titlePriceLayout = value.toUpperCase();
          break;
        case 'ribbonPlacement':
          ribbonUpdates.ribbonPlacement = value.toUpperCase();
          break;
        default:
          unreachable(styleKey);
          return null;
      }
    });

    patchPmNodeAttrs({
      imageStyles: {
        ...pmNodeAttrs?.imageStyles,
        ...imageUpdates,
      },
      cardStyles: {
        ...pmNodeAttrs?.cardStyles,
        ...cardUpdates,
      },
      ribbonStyles: {
        ...pmNodeAttrs?.ribbonStyles,
        ...ribbonUpdates,
      },
    });
  };

  return (
    <Accordion
      hideShadow
      skin="light"
      size="medium"
      multiple
      items={[
        accordionItemBuilder({
          initiallyOpen: true,
          title: (
            <Text size="small" weight="bold">
              {t('Embed_Vertical_Layout_Panel_Image_Section')}
            </Text>
          ),
          children: (
            <Box direction="vertical" gap="SP2">
              <FormField
                label={t('Embed_Vertical_Layout_Panel_Position_Label')}
                labelPlacement="left"
                labelWidth="1fr"
              >
                <Box direction="horizontal" gap={'SP1'} align="left">
                  <Tooltip
                    size="small"
                    inline
                    content={
                      isRTL
                        ? t('Embed_Vertical_Layout_Panel_Position_Right')
                        : t('Embed_Vertical_Layout_Panel_Position_Left')
                    }
                    appendTo={containerEl}
                  >
                    <Thumbnail
                      size="tiny"
                      selected={position === AppEmbedData_ImageStyles_Position.START}
                      onClick={() => {
                        logBi({ dataHook: 'VERTICAL_EMBED_POSITION_START' });
                        updateStyles({ position: AppEmbedData_ImageStyles_Position.START });
                      }}
                      noPadding
                      width={30}
                      height={30}
                      contentAlignment="center"
                      textPosition="outside"
                      image={
                        isRTL ? (
                          <Box height="100%" width="100%" align="center" verticalAlign="middle">
                            <ObjectPositionRightSmall />
                          </Box>
                        ) : (
                          <Box height="100%" width="100%" align="center" verticalAlign="middle">
                            <ObjectPositionLeftSmall />
                          </Box>
                        )
                      }
                      dataHook="VERTICAL_EMBED_POSITION_START"
                    />
                  </Tooltip>

                  <Tooltip
                    size="small"
                    inline
                    content={t('Embed_Vertical_Layout_Panel_Position_Top')}
                    appendTo={containerEl}
                  >
                    <Thumbnail
                      size="tiny"
                      selected={position === AppEmbedData_ImageStyles_Position.TOP}
                      onClick={() => {
                        logBi({ dataHook: 'VERTICAL_EMBED_POSITION_TOP' });
                        updateStyles({ position: AppEmbedData_ImageStyles_Position.TOP });
                      }}
                      noPadding
                      width={30}
                      height={30}
                      contentAlignment="center"
                      textPosition="outside"
                      image={
                        <Box height="100%" width="100%" align="center" verticalAlign="middle">
                          <ObjectPositionTopSmall />
                        </Box>
                      }
                      dataHook="VERTICAL_EMBED_POSITION_TOP"
                    />
                  </Tooltip>

                  <Tooltip
                    size="small"
                    inline
                    content={
                      isRTL
                        ? t('Embed_Vertical_Layout_Panel_Position_Left')
                        : t('Embed_Vertical_Layout_Panel_Position_Right')
                    }
                    appendTo={containerEl}
                  >
                    <Thumbnail
                      size="tiny"
                      selected={position === AppEmbedData_ImageStyles_Position.END}
                      onClick={() => {
                        logBi({ dataHook: 'VERTICAL_EMBED_POSITION_END' });
                        updateStyles({ position: AppEmbedData_ImageStyles_Position.END });
                      }}
                      noPadding
                      width={30}
                      height={30}
                      contentAlignment="center"
                      textPosition="outside"
                      image={
                        isRTL ? (
                          <Box height="100%" width="100%" align="center" verticalAlign="middle">
                            <ObjectPositionLeftSmall />
                          </Box>
                        ) : (
                          <Box height="100%" width="100%" align="center" verticalAlign="middle">
                            <ObjectPositionRightSmall />
                          </Box>
                        )
                      }
                      dataHook="VERTICAL_EMBED_POSITION_END"
                    />
                  </Tooltip>
                </Box>
              </FormField>

              <FormField
                label={t('Embed_Vertical_Layout_Panel_Ratio_Label')}
                labelPlacement="left"
                labelWidth="1fr"
              >
                <Box direction="horizontal" gap={'SP1'} align="left">
                  <Tooltip
                    size="small"
                    inline
                    content={t('Embed_Vertical_Layout_Panel_Ratio_Square')}
                    appendTo={containerEl}
                  >
                    <Thumbnail
                      size="tiny"
                      selected={ratio === AppEmbedData_ImageStyles_AspectRatio.SQUARE}
                      onClick={() => {
                        logBi({ dataHook: 'VERTICAL_EMBED_RATIO_SQUARE' });
                        updateStyles({ ratio: AppEmbedData_ImageStyles_AspectRatio.SQUARE });
                      }}
                      noPadding
                      width={30}
                      height={30}
                      contentAlignment="center"
                      textPosition="outside"
                      image={
                        <Box height="100%" width="100%" align="center" verticalAlign="middle">
                          <SquareRatioSmall />
                        </Box>
                      }
                      dataHook="VERTICAL_EMBED_RATIO_SQUARE"
                    />
                  </Tooltip>

                  <Tooltip
                    size="small"
                    inline
                    content={t('Embed_Vertical_Layout_Panel_Ratio_Rectangle')}
                    appendTo={containerEl}
                  >
                    <Thumbnail
                      size="tiny"
                      selected={ratio === AppEmbedData_ImageStyles_AspectRatio.RECTANGLE}
                      onClick={() => {
                        logBi({ dataHook: 'VERTICAL_EMBED_RATIO_RECTANGLE' });
                        updateStyles({ ratio: AppEmbedData_ImageStyles_AspectRatio.RECTANGLE });
                      }}
                      noPadding
                      width={30}
                      height={30}
                      contentAlignment="center"
                      textPosition="outside"
                      image={
                        <Box height="100%" width="100%" align="center" verticalAlign="middle">
                          <HorizontalRatioSmall />
                        </Box>
                      }
                      dataHook="VERTICAL_EMBED_RATIO_RECTANGLE"
                    />
                  </Tooltip>
                </Box>
              </FormField>

              <FormField
                label={t('Embed_Vertical_Layout_Panel_Resizing_Label')}
                labelPlacement="left"
                labelWidth="1fr"
                inputWidth="116px"
              >
                <Dropdown
                  size="small"
                  placeholder={t('Embed_Vertical_Layout_Panel_Resizing_Placeholder')}
                  selectedId={resizing}
                  onSelect={({ id }) => {
                    logBi({ dataHook: 'VERTICAL_EMBED_RESIZING_CHANGE', value: id });
                    updateStyles({ resizing: id as string });
                  }}
                  options={[
                    {
                      id: 'FILL',
                      value: t('Embed_Vertical_Layout_Panel_Resizing_Fill'),
                    },
                    {
                      id: 'FIT',
                      value: t('Embed_Vertical_Layout_Panel_Resizing_Fit'),
                    },
                  ]}
                  dataHook="VERTICAL_EMBED_RESIZING_DROPDOWN"
                />
              </FormField>
            </Box>
          ),
        }),
        accordionItemBuilder({
          initiallyOpen: true,
          title: (
            <Text size="small" weight="bold">
              {t('Embed_Vertical_Layout_Panel_Information_Section')}
            </Text>
          ),
          children: (
            <Box direction="vertical" gap="SP2">
              <FormField
                label={t('Embed_Vertical_Layout_Panel_Alignment_Label')}
                labelPlacement="left"
                labelWidth="1fr"
              >
                <Box direction="horizontal" gap={'SP1'} align="left">
                  <Tooltip
                    size="small"
                    inline
                    content={t('Embed_Vertical_Layout_Panel_Alignment_Left')}
                    appendTo={containerEl}
                  >
                    <Thumbnail
                      size="tiny"
                      selected={alignment === AppEmbedData_CardStyles_Alignment.START}
                      onClick={() => {
                        logBi({ dataHook: 'VERTICAL_EMBED_ALIGNMENT_LEFT' });
                        updateStyles({ alignment: AppEmbedData_CardStyles_Alignment.START });
                      }}
                      noPadding
                      width={30}
                      height={30}
                      contentAlignment="center"
                      textPosition="outside"
                      image={
                        <Box height="100%" width="100%" align="center" verticalAlign="middle">
                          <AlignLeftSmall />
                        </Box>
                      }
                      dataHook="VERTICAL_EMBED_ALIGNMENT_LEFT"
                    />
                  </Tooltip>

                  <Tooltip
                    size="small"
                    inline
                    content={t('Embed_Vertical_Layout_Panel_Alignment_Center')}
                    appendTo={containerEl}
                  >
                    <Thumbnail
                      size="tiny"
                      selected={alignment === 'CENTER'}
                      onClick={() => {
                        logBi({ dataHook: 'VERTICAL_EMBED_ALIGNMENT_CENTER' });
                        updateStyles({ alignment: 'CENTER' });
                      }}
                      noPadding
                      width={30}
                      height={30}
                      contentAlignment="center"
                      textPosition="outside"
                      image={
                        <Box height="100%" width="100%" align="center" verticalAlign="middle">
                          <AlignCenterVerticallySmall />
                        </Box>
                      }
                      dataHook="VERTICAL_EMBED_ALIGNMENT_CENTER"
                    />
                  </Tooltip>

                  <Tooltip
                    size="small"
                    inline
                    content={t('Embed_Vertical_Layout_Panel_Alignment_Right')}
                    appendTo={containerEl}
                  >
                    <Thumbnail
                      size="tiny"
                      selected={alignment === AppEmbedData_CardStyles_Alignment.END}
                      onClick={() => {
                        logBi({ dataHook: 'VERTICAL_EMBED_ALIGNMENT_RIGHT' });
                        updateStyles({ alignment: AppEmbedData_CardStyles_Alignment.END });
                      }}
                      noPadding
                      width={30}
                      height={30}
                      contentAlignment="center"
                      textPosition="outside"
                      image={
                        <Box height="100%" width="100%" align="center" verticalAlign="middle">
                          <AlignRightSmall />
                        </Box>
                      }
                      dataHook="VERTICAL_EMBED_ALIGNMENT_RIGHT"
                    />
                  </Tooltip>
                </Box>
              </FormField>

              <FormField
                label={t('Embed_Vertical_Layout_Panel_Title_Price_Label')}
                labelPlacement="left"
                labelWidth="1fr"
              >
                <Box direction="horizontal" gap={'SP1'} align="left">
                  <Tooltip
                    size="small"
                    inline
                    content={t('Embed_Vertical_Layout_Panel_Title_Price_Stacked')}
                    appendTo={containerEl}
                  >
                    <Thumbnail
                      size="tiny"
                      selected={titlePriceLayout === TITLE_PRICE_LAYOUT.STACKED}
                      onClick={() => {
                        logBi({ dataHook: 'VERTICAL_EMBED_TITLE_PRICE_STACKED' });
                        updateStyles({ titlePriceLayout: TITLE_PRICE_LAYOUT.STACKED });
                      }}
                      noPadding
                      width={30}
                      height={30}
                      contentAlignment="center"
                      textPosition="outside"
                      image={
                        <Box height="100%" width="100%" align="center" verticalAlign="middle">
                          <LayoutSplitSmall />
                        </Box>
                      }
                      dataHook="VERTICAL_EMBED_TITLE_PRICE_STACKED"
                    />
                  </Tooltip>

                  <Tooltip
                    size="small"
                    inline
                    content={t('Embed_Vertical_Layout_Panel_Title_Price_SideBySide')}
                    appendTo={containerEl}
                  >
                    <Thumbnail
                      size="tiny"
                      selected={titlePriceLayout === 'SIDE_BY_SIDE'}
                      onClick={() => {
                        logBi({ dataHook: 'VERTICAL_EMBED_TITLE_PRICE_SIDE_BY_SIDE' });
                        updateStyles({ titlePriceLayout: 'SIDE_BY_SIDE' });
                      }}
                      noPadding
                      width={30}
                      height={30}
                      contentAlignment="center"
                      textPosition="outside"
                      image={
                        <Box height="100%" width="100%" align="center" verticalAlign="middle">
                          <LayoutTwoColumnsSplitSmall />
                        </Box>
                      }
                      dataHook="VERTICAL_EMBED_TITLE_PRICE_SIDE_BY_SIDE"
                    />
                  </Tooltip>
                </Box>
              </FormField>

              <FormField
                label={t('Embed_Vertical_Layout_Panel_Ribbon_Placement_Label')}
                labelPlacement="left"
                labelWidth="1fr"
              >
                <Box direction="horizontal" gap={'SP1'} align="left">
                  <Tooltip
                    size="small"
                    inline
                    content={t('Embed_Vertical_Layout_Panel_Ribbon_Placement_OnImage')}
                    appendTo={containerEl}
                  >
                    <Thumbnail
                      size="tiny"
                      selected={ribbonPlacement === AppEmbedData_RibbonStyles_Placement.IMAGE}
                      onClick={() => {
                        logBi({ dataHook: 'VERTICAL_EMBED_RIBBON_PLACEMENT_ON_IMAGE' });
                        updateStyles({
                          ribbonPlacement: AppEmbedData_RibbonStyles_Placement.IMAGE,
                        });
                      }}
                      noPadding
                      width={30}
                      height={30}
                      contentAlignment="center"
                      textPosition="outside"
                      image={
                        <Box height="100%" width="100%" align="center" verticalAlign="middle">
                          <ImageSmall />
                        </Box>
                      }
                      dataHook="VERTICAL_EMBED_RIBBON_PLACEMENT_ON_IMAGE"
                    />
                  </Tooltip>

                  <Tooltip
                    size="small"
                    inline
                    content={t('Embed_Vertical_Layout_Panel_Ribbon_Placement_AboveInfo')}
                    appendTo={containerEl}
                  >
                    <Thumbnail
                      size="tiny"
                      selected={
                        ribbonPlacement === AppEmbedData_RibbonStyles_Placement.PRODUCT_INFO
                      }
                      onClick={() => {
                        logBi({ dataHook: 'VERTICAL_EMBED_RIBBON_PLACEMENT_ABOVE_INFO' });
                        updateStyles({
                          ribbonPlacement: AppEmbedData_RibbonStyles_Placement.PRODUCT_INFO,
                        });
                      }}
                      noPadding
                      width={30}
                      height={30}
                      contentAlignment="center"
                      textPosition="outside"
                      image={
                        <Box height="100%" width="100%" align="center" verticalAlign="middle">
                          <BadgeSmall />
                        </Box>
                      }
                      dataHook="VERTICAL_EMBED_RIBBON_PLACEMENT_ABOVE_INFO"
                    />
                  </Tooltip>
                </Box>
              </FormField>
            </Box>
          ),
        }),
      ]}
    />
  );
};
