import { Box, ListItemSelect, Text } from '@wix/design-system';
import React, { useContext, useEffect, useRef, useState } from 'react';

import { RicosContext, ZIndexContext } from './../../ricos-context/index.js';
import { Image } from './../../ui-components/index.js';

import type { ContentType } from '../constants.js';
import { convertDurations } from '../convert-duration.js';
import { INSERT_VERTICAL_EMBED_MODAL_ITEM } from '../data-hooks.js';
import type { EmbeddableItem } from '../types.js';
import classes from './items-list-scss.js';

type ItemsListProps = {
  items: EmbeddableItem[];
  onClick: (item: EmbeddableItem) => void;
  selectedItem?: EmbeddableItem;
  contentType: ContentType;
  modalRef?: HTMLDivElement | null;
  hasActiveSearch?: boolean;
  listboxId?: string;
};

export const ItemsList: React.FC<ItemsListProps> = ({
  items,
  onClick,
  selectedItem,
  contentType,
  modalRef,
  hasActiveSearch = false,
  listboxId,
}) => {
  const { t } = useContext(RicosContext);
  const zIndexService = useContext(ZIndexContext);
  const listboxRef = useRef<HTMLDivElement>(null);
  const [focusedIndex, setFocusedIndex] = useState(0);

  useEffect(() => {
    setFocusedIndex(0);
  }, [items]);

  if (items.length === 0) {
    const emptyStateSuffix = hasActiveSearch ? 'NoResults' : 'NoItems';
    return (
      <Box direction="vertical" margin="SP4" gap="SP2" textAlign="center">
        <Text size="medium" weight="bold" secondary>
          {t(`Embed_Vertical_${contentType}_EmptyState_${emptyStateSuffix}_Title`)}
        </Text>
        <Text size="small" secondary>
          {t(`Embed_Vertical_${contentType}_EmptyState_${emptyStateSuffix}_Description`)}
        </Text>
      </Box>
    );
  }

  const currentIndex = Math.min(focusedIndex, items.length - 1);

  const focusOption = (index: number) => {
    setFocusedIndex(index);
    const options = listboxRef.current?.querySelectorAll<HTMLElement>('[role="option"]');
    options?.[index]?.focus();
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const nextIndex =
      e.key === 'ArrowDown'
        ? Math.min(currentIndex + 1, items.length - 1)
        : e.key === 'ArrowUp'
          ? Math.max(currentIndex - 1, 0)
          : e.key === 'Home'
            ? 0
            : e.key === 'End'
              ? items.length - 1
              : undefined;

    if (nextIndex === undefined) {
      return;
    }

    e.preventDefault();
    e.stopPropagation();
    focusOption(nextIndex);
  };

  return (
    <div
      ref={listboxRef}
      role="listbox"
      id={listboxId}
      aria-label={t('Embed_Vertical_ItemsList_AriaLabel')}
      onKeyDown={onKeyDown}
    >
      {items.map((item, index) => {
        return (
          <div
            key={item.id}
            role="option"
            aria-selected={selectedItem?.id === item.id}
            tabIndex={index === currentIndex ? 0 : -1}
            className={classes.option}
            onFocus={() => setFocusedIndex(index)}
            onClick={() => onClick(item)}
            onKeyDown={e => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                e.stopPropagation();
                onClick(item);
              }
            }}
          >
            <ListItemSelect
              size="small"
              dataHook={INSERT_VERTICAL_EMBED_MODAL_ITEM}
              title={item.title}
              selected={selectedItem?.id === item.id}
              ellipsis
              prefix={
                <Box width="50px" height="50px" margin="6px 6px 6px 0">
                  {(item.image?.id || item.image?.url) && (
                    <Image
                      uri={item.image.id ?? item.image.url!}
                      width={50}
                      height={50}
                      displayMode="fill"
                      alt=""
                      shouldUseLQIP={false}
                    />
                  )}
                </Box>
              }
              subtitle={
                contentType === 'Bookings'
                  ? convertDurations(item.bookingDetails?.durations, t) || undefined
                  : contentType === 'Events'
                    ? `${item.eventDetails?.formattedDateAndTime} | ${item.eventDetails?.location}`
                    : undefined
              }
              tooltipProps={{
                appendTo: modalRef ?? undefined,
                zIndex: zIndexService.getZIndex('TOOLTIP'),
                children: [],
                enterDelay: 1000,
                placement: 'top',
              }}
            />
          </div>
        );
      })}
    </div>
  );
};
