import { TIPTAP_APP_EMBED_TYPE } from './../../ricos-content/index.js';
import type { ExtensionProps, NodeConfig, RicosExtension } from './../../ricos-types/index.js';
import type { CommandProps } from './../../tiptap/core/index.js';
import { Plugin, PluginKey } from './../../tiptap/pm/state.js';
import { Decoration, DecorationSet } from './../../tiptap/pm/view.js';
import { createRicosNodeExtension } from './../../plugin-commons/index.js';

import { AppEmbed as Component } from './component.js';

declare module './../../tiptap/core' {
  interface Commands<ReturnType> {
    verticalEmbed: {
      /**
       * Sets value of temporary hover preview in Vertical Embed settings.
       */
      setVerticalEmbedButtonHoverPreview: (applyPreview: boolean) => ReturnType;
    };
  }
}

export const tiptapExtensions = [
  createRicosNodeExtension({
    groups: [
      'draggable',
      'not-overtypable',
      { group: 'resizable', options: { expandToFullWidthOnOverdrag: true } },
    ],
    type: 'react-node',
    reconfigure: (
      config: NodeConfig,
      _extensions: RicosExtension[],
      _props: ExtensionProps,
      settings: Record<string, unknown>
    ) => ({
      ...config,
      addOptions: () => settings,
    }),
    Component,
    name: TIPTAP_APP_EMBED_TYPE,
    createExtensionConfig() {
      const HOVER_PREVIEW_PLUGIN_KEY = new PluginKey('verticalEmbedHoverPreview');

      return {
        name: this.name,
        group:
          'block smartBlockCellContent layoutCellContent collapsibleListItemBodyContent tableCellContent',
        selectable: true,
        draggable: true,
        addAttributes: () => ({
          type: null,
          name: null,
          url: null,
          image: null,
          itemId: null,
          hideImage: null,
          hidePrice: null,
          hideButton: null,
          hideRibbon: null,
          hideDescription: null,
          hideDateTime: null,
          hideLocation: null,
          hideDuration: null,
          buttonStyles: null,
          imageStyles: null,
          ribbonStyles: null,
          cardStyles: null,
          bookingData: null,
          eventData: null,
          containerData: null,
          loading: null,
          error: null,
          pricingData: null,
        }),
        addCommands() {
          return {
            setVerticalEmbedButtonHoverPreview:
              (applyPreview: boolean) =>
              ({ tr, dispatch }: CommandProps) => {
                dispatch?.(tr.setMeta(HOVER_PREVIEW_PLUGIN_KEY, applyPreview));

                return true;
              },
          };
        },
        addProseMirrorPlugins() {
          return [
            new Plugin({
              key: HOVER_PREVIEW_PLUGIN_KEY,

              state: {
                init() {
                  return { applyPreview: false };
                },
                apply(tr, value) {
                  const applyPreview = tr.getMeta(HOVER_PREVIEW_PLUGIN_KEY);

                  if (applyPreview === undefined) {
                    return value;
                  }

                  return { applyPreview };
                },
              },

              props: {
                decorations(state) {
                  const { applyPreview } = HOVER_PREVIEW_PLUGIN_KEY.getState(state);
                  const { from, to } = state.selection;

                  if (!applyPreview) {
                    return null;
                  }

                  return DecorationSet.create(state.doc, [
                    Decoration.node(from, to, {
                      class: 'forced-hover',
                    }),
                  ]);
                },
              },
            }),
          ];
        },
      };
    },
  }),
];
