import React from 'react';

import { useDevVerticalEmbedItem, useDevVerticalEmbedItems } from './../../ricos-context/index.js';
import { useRequestService } from './../../_shared/request-service-provider/request-service-provider.js';

import type {
  EmbeddableItem,
  GetEmbeddableItemResponse,
  ItemType,
  ListEmbeddableItemsRequest,
  ListEmbeddableItemsResponse,
  VerticalApiType,
} from '../types.js';

const convertToItemType = (type: VerticalApiType): ItemType => {
  switch (type) {
    case 'product':
      return 'PRODUCT';
    case 'event':
      return 'EVENT';
    case 'booking':
      return 'BOOKING';
    default:
      return 'UNKNOWN_ITEM_TYPE';
  }
};

export type VerticalEmbedRequestService = {
  fetchVerticalEmbedItems: (type: VerticalApiType, query?: string) => Promise<EmbeddableItem[]>;
  fetchVerticalEmbedItem: (type: VerticalApiType, embedId: string) => Promise<EmbeddableItem>;
};

const baseUrl =
  typeof location !== 'undefined' && location.hostname === 'editor.wix.com'
    ? 'https://editor.wix.com/_api/ricos-embeddables/v1/embeddable-items/'
    : 'https://www.wixapis.com/ricos/v1/embeddable-items';

const buildListEmbeddableItemsUrl = (): string => {
  return `${baseUrl}/list`;
};

const buildGetEmbeddableItemUrl = (itemId: string, itemType: ItemType): string => {
  return `${baseUrl}/${itemId}?itemType=${itemType}`;
};

export const useVerticalEmbedRequestService = (): VerticalEmbedRequestService => {
  const { makeRequest } = useRequestService();
  const devVerticalEmbedService = useDevVerticalEmbedItems();
  const devVerticalEmbedItemService = useDevVerticalEmbedItem();

  const fetchVerticalEmbedItems = async (
    type: VerticalApiType,
    query: string = ''
  ): Promise<EmbeddableItem[]> => {
    if (devVerticalEmbedService) {
      return devVerticalEmbedService(type, query);
    }

    const itemType = convertToItemType(type);
    const requestBody: ListEmbeddableItemsRequest = {
      itemType,
      limit: 50,
    };

    if (query) {
      requestBody.query = query;
    }

    const url = buildListEmbeddableItemsUrl();

    try {
      const response = await makeRequest(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(requestBody),
      });

      if (!response.ok) {
        const error = new Error(`Error while fetching vertical embed items: ${response.status}`);
        (error as any).status = response.status;
        throw error;
      }

      const data: ListEmbeddableItemsResponse = await response.json();

      return data.items;
    } catch (error) {
      console.error('Failed to fetch vertical embed items:', error);
      throw error;
    }
  };

  const fetchVerticalEmbedItem = async (
    type: VerticalApiType,
    embedId: string
  ): Promise<EmbeddableItem> => {
    if (devVerticalEmbedItemService) {
      return devVerticalEmbedItemService(type, embedId);
    }

    const url = buildGetEmbeddableItemUrl(embedId, convertToItemType(type));

    try {
      const response = await makeRequest(url, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        const error = new Error(`Error while fetching vertical embed item: ${response.status}`);
        (error as any).status = response.status;
        throw error;
      }

      const data: GetEmbeddableItemResponse = await response.json();

      return data.embeddableItem;
    } catch (error) {
      console.error('Failed to fetch vertical embed item:', error);
      throw error;
    }
  };

  return React.useMemo(() => {
    return {
      fetchVerticalEmbedItems,
      fetchVerticalEmbedItem,
    };
  }, [makeRequest]);
};
