import { DateSmall, LocationSmall, TimeSmall } from '@wix/wix-ui-icons-common/lazy';
import React from 'react';

import type { AppEmbedData } from './../../ricos-schema/next-schema/index.js';
import { VERTICAL_EMBED_SUBTITLE } from './../data-hooks.js';

import styles from './description-scss.js';

export const Description: React.FC<{ componentData: AppEmbedData }> = ({ componentData }) => {
  if (componentData.type === 'EVENT' && componentData.eventData) {
    const { scheduling, location } = componentData.eventData;
    const showDateTime = !componentData.hideDateTime && scheduling;
    const showLocation = !componentData.hideLocation && location;

    if (!showDateTime && !showLocation) {
      return null;
    }

    return (
      <div className={styles.subtitle} data-hook={VERTICAL_EMBED_SUBTITLE}>
        {showDateTime && <DescriptionItem icon={<DateSmall />} text={scheduling} />}
        {showLocation && <DescriptionItem icon={<LocationSmall />} text={location} />}
      </div>
    );
  }

  if (componentData.type === 'BOOKING' && componentData.bookingData) {
    const { durations } = componentData.bookingData;
    const showDuration = !componentData.hideDuration && durations;

    if (!showDuration) {
      return null;
    }

    return (
      <div className={styles.subtitle} data-hook={VERTICAL_EMBED_SUBTITLE}>
        <DescriptionItem icon={<TimeSmall />} text={durations} />
      </div>
    );
  }

  return null;
};

const DescriptionItem = ({ icon, text }: { icon: React.ReactNode; text: string }) => (
  <span className={styles.descriptionItem}>
    {icon}
    {text}
  </span>
);
