import type { AppEmbedData } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import {
  AppEmbedData_AppType,
  PluginContainerData_Alignment,
  PluginContainerData_Width_Type,
} from './../ricos-schema/legacy/wix/rich_content/v1/index.js';

import { convertDurations } from './convert-duration.js';
import type { EmbeddableItem, VerticalApiType } from './types.js';

export const isTypeAppEmbed = (type: any): type is AppEmbedData_AppType =>
  Object.values(AppEmbedData_AppType).includes(type);

export const getLowerCaseAppEmbedType = (type: AppEmbedData_AppType): VerticalApiType =>
  type.toLowerCase() as VerticalApiType;

const mapVerticalData = (
  item: EmbeddableItem,
  componentType: AppEmbedData_AppType,
  t: (key: string) => string
) => {
  switch (componentType) {
    case 'BOOKING':
      return {
        bookingData: {
          durations: convertDurations(item.bookingDetails?.durations, t),
        },
      };
    case 'EVENT':
      return {
        eventData: {
          scheduling: item.eventDetails?.formattedDateAndTime,
          location: item.eventDetails?.location,
        },
      };
    default:
      return {};
  }
};

const mapPricingData = (item: EmbeddableItem) => {
  if (!item.pricingData) {
    return undefined;
  }

  return {
    valueFrom: item.pricingData.minValue,
    valueTo: item.pricingData.maxValue,
    discountedValue: item.pricingData.discountedValue,
    currency: item.pricingData.currency,
    pricingPlanId: item.pricingData.pricingPlanId,
  };
};

const mapImageData = (item: EmbeddableItem) => ({
  src: item.image?.id ? { id: item.image?.id } : { url: item.image?.url },
  height: item.image?.height,
  width: item.image?.width,
});

export const toAppEmbedData = (
  item: EmbeddableItem,
  componentData: AppEmbedData,
  t: (key: string) => string
): AppEmbedData => {
  const mappedVerticalData = mapVerticalData(item, componentData.type, t);
  const mappedPricingData = mapPricingData(item);
  const mappedImage = mapImageData(item);

  return {
    containerData: {
      width: {
        size: PluginContainerData_Width_Type.CONTENT,
      },
      alignment: PluginContainerData_Alignment.CENTER,
      textWrap: false,
    },
    ...item,
    ...componentData,
    name: item.title,
    itemId: item.id,
    url: item.pageUrl,
    image: mappedImage,
    pricingData: mappedPricingData,
    ...mappedVerticalData,
  };
};

export const hasOnlyDefaults = (styleObj: any, defaults: Record<string, any>): boolean => {
  if (!styleObj) {
    return true;
  }

  const enumsAreDefault = Object.entries(defaults).every(
    ([key, defaultValue]) => styleObj[key] === defaultValue || styleObj[key] === undefined
  );

  const hasCustomProps = Object.keys(styleObj).some(key => !(key in defaults));

  return enumsAreDefault && !hasCustomProps;
};
