import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { ModalServiceContext } from './../../ricos-context/modal-context.js';
import type {
  AppEmbedData_ButtonStyles,
  AppEmbedData_CardStyles,
  AppEmbedData_RibbonStyles,
} from './../../ricos-schema/next-schema/generated/ricos_document.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import {
  handleColorAdded,
  handleColorDeleted,
  resolveThemeColorsPalette,
  useResolvedCustomColors,
} from './../../_shared/color-manager-utils.js';
import { PmNodeType } from './../../_shared/pm-node-types.js';
import { unreachable } from './../../_shared/uncreachable.js';
import { useNodeAttrs } from './../../_shared/use-node-attrs.js';
import { NewColorPicker } from './../../ui-components/color-picker/new-color-picker/index.js';

import type { VerticalEmbedPluginEditorConfig } from '../types.js';

export type VerticalEmbedColorType =
  | 'titleColor'
  | 'textColor'
  | 'backgroundColor'
  | 'borderColor'
  | 'buttonBackgroundColor'
  | 'buttonTextColor'
  | 'buttonBorderColor'
  | 'buttonBackgroundColorHover'
  | 'buttonTextColorHover'
  | 'buttonBorderColorHover'
  | 'ribbonFillColor'
  | 'ribbonTextColor'
  | 'ribbonBorderColor'
  | 'imageBorderColor';

type VerticalEmbedColorPickerProps = {
  modalId: string;
  nodeId: string;
  colorType: VerticalEmbedColorType;
  referenceElement: HTMLDivElement | undefined;
  config: VerticalEmbedPluginEditorConfig;
  onColorSelected: (color: string | undefined) => void;
  defaultColor?: string;
};

const getColorFromStyles = (
  styles:
    | {
        buttonStyles?: AppEmbedData_ButtonStyles | null;
        cardStyles?: AppEmbedData_CardStyles | null;
        ribbonStyles?: AppEmbedData_RibbonStyles | null;
        imageStyles?: { borderColor?: string | null } | null;
      }
    | undefined,
  colorType: VerticalEmbedColorType
): string | null | undefined => {
  if (!styles) {
    return undefined;
  }

  switch (colorType) {
    case 'titleColor':
      return styles.cardStyles?.titleColor;
    case 'textColor':
      return styles.cardStyles?.textColor;
    case 'backgroundColor':
      return styles.cardStyles?.backgroundColor;
    case 'borderColor':
      return styles.cardStyles?.borderColor;
    case 'buttonBackgroundColor':
      return styles.buttonStyles?.backgroundColor;
    case 'buttonTextColor':
      return styles.buttonStyles?.textColor;
    case 'buttonBorderColor':
      return styles.buttonStyles?.borderColor;
    case 'buttonBackgroundColorHover':
      return styles.buttonStyles?.backgroundColorHover;
    case 'buttonTextColorHover':
      return styles.buttonStyles?.textColorHover;
    case 'buttonBorderColorHover':
      return styles.buttonStyles?.borderColorHover;
    case 'ribbonFillColor':
      return styles.ribbonStyles?.backgroundColor;
    case 'ribbonTextColor':
      return styles.ribbonStyles?.textColor;
    case 'ribbonBorderColor':
      return styles.ribbonStyles?.borderColor;
    case 'imageBorderColor':
      return styles.imageStyles?.borderColor;
    default:
      unreachable(colorType);
      return undefined;
  }
};

export const VerticalEmbedColorPicker: React.FC<VerticalEmbedColorPickerProps> = ({
  modalId,
  nodeId,
  colorType,
  referenceElement,
  config,
  onColorSelected,
  defaultColor,
}) => {
  const modalService = useContext(ModalServiceContext);
  const { t, colorManager, theme } = useContext(RicosContext);

  const { pmNodeAttrs } = useNodeAttrs(nodeId, PmNodeType.APP_EMBED);

  const logBi = useBiNext({
    modalId,
    pluginId: 'verticalEmbed',
    nodeId,
  });

  const themeColors = resolveThemeColorsPalette(
    theme,
    config?.colors ? Object.values(config.colors) : []
  );

  const currentStyleColor = getColorFromStyles(
    {
      buttonStyles: pmNodeAttrs?.buttonStyles,
      cardStyles: pmNodeAttrs?.cardStyles,
      ribbonStyles: pmNodeAttrs?.ribbonStyles,
      imageStyles: pmNodeAttrs?.imageStyles,
    },
    colorType
  );

  const customColors = useResolvedCustomColors(colorManager);

  const onColorAdded = (color: string) => {
    handleColorAdded(color, colorManager);
    onColorSelected(color);
  };

  const onColorDeleted = (color: string) => {
    handleColorDeleted(color, colorManager);
  };

  const closeModal = () => modalService.closeModal(modalId);

  const onResetColor = () => onColorSelected(undefined);

  const currentColor = (currentStyleColor ?? defaultColor)?.toUpperCase();

  const textColorTypes: ReadonlySet<VerticalEmbedColorType> = new Set([
    'titleColor',
    'textColor',
    'buttonTextColor',
    'buttonTextColorHover',
    'ribbonTextColor',
  ]);

  const allowTransparent = !textColorTypes.has(colorType);

  return (
    <NewColorPicker
      themeColors={themeColors}
      customColors={customColors}
      currentColor={currentColor}
      title={t('ButtonColourModal_Title')}
      closeModal={closeModal}
      onColorSelected={onColorSelected}
      onColorAdded={onColorAdded}
      onColorDeleted={onColorDeleted}
      onResetColor={onResetColor}
      referenceElement={referenceElement}
      logBi={logBi}
      allowTransparent={allowTransparent}
    />
  );
};
